package com.example.shop.jpa_tsql;

import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.sql.DataSource;

/** Runs the CustomerOrders query. Named parameters are bound by position (JDBC uses ?). */
public final class CustomerOrdersQuery {
    private static final String SQL = """
            SELECT c.Id, c.Name, o.Total, o.OrderDate
            FROM dbo.Customers c
            JOIN dbo.Orders o ON o.CustomerId = c.Id
            WHERE c.Id = ? AND o.Total > ?
            ORDER BY o.OrderDate DESC""";

    private final DataSource dataSource;

    public CustomerOrdersQuery(DataSource dataSource) {
        this.dataSource = Objects.requireNonNull(dataSource, "dataSource");
    }

    public List<CustomerOrdersRow> run(Integer customerId, BigDecimal minTotal) throws SQLException {
        try (Connection c = dataSource.getConnection();
                PreparedStatement ps = c.prepareStatement(SQL)) {
            ps.setObject(1, customerId, Types.INTEGER);
            ps.setBigDecimal(2, minTotal);
            try (ResultSet rs = ps.executeQuery()) {
                List<CustomerOrdersRow> list = new ArrayList<>();
                while (rs.next()) {
                    list.add(new CustomerOrdersRow(
                            rs.getInt("Id"),
                            rs.getString("Name"),
                            rs.getBigDecimal("Total"),
                            rs.getObject("OrderDate", LocalDateTime.class)));
                }
                return list;
            }
        }
    }
}
